/* Generated by Payload at first, then customised: the one change is the guard around RootPage (see payload/admin/login-bounce-guard.tsx).
   Payload tooling does not rewrite this file in this project. */
import type { Metadata } from 'next'
import { headers as nextHeaders } from 'next/headers'

import config from '@payload-config'
import { getPayload } from 'payload'
import { RootPage, generatePageMetadata } from '@payloadcms/next/views'
import { loginBounceNotice } from '@/payload/admin/login-bounce-guard'
import { importMap } from '../importMap'

type Args = {
  params: Promise<{
    segments: string[]
  }>
  searchParams: Promise<{
    [key: string]: string | string[]
  }>
}

export const generateMetadata = ({ params, searchParams }: Args): Promise<Metadata> =>
  generatePageMetadata({ config, params, searchParams })

const Page = async ({ params, searchParams }: Args) => {
  try {
    return await RootPage({ config, params, searchParams, importMap })
  } catch (error) {
    // A redirect to the login page while a sign-in cookie is present may be a failed session lookup, not a signed-out visitor.
    const notice = await loginBounceNotice({ error, payload: await getPayload({ config }), headers: await nextHeaders() })
    if (notice !== null) return notice
    throw error
  }
}

export default Page
